args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Tenth_Avenue_Angel dbr:Brink_of_Life }
  ?film dbo:director ?director .
  OPTIONAL { ?director (dbo:deathDate|dbp:deathDate) ?deathDate . }
}
ORDER BY DESC(?deathDate)
LIMIT 1

